// Des: Reply to new comments in the owner's tone
// Flo: open comments page > read each comment (read-only) > draft reply (AI if on, else template) > reply through the safety ladder > skip replied ones
// I/O: Args maxn (caller) > replies sent or previewed; each comment is answered once (key = comment text)
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const flow = @import("ru-flow-runz.zig"); const pace = @import("ru-huma-pace.zig"); const post = @import("ru-post-main.zig");
const CF = .{ .read = "Array.from(document.querySelectorAll('[role=article]')).map(function(a){return a.innerText.split('\\n')[0].trim()})", .dflt = "Thank you!", .aipr = "Write one short, friendly reply (max 25 words, same language as the comment, no emoji spam) to this Facebook comment: " };
pub fn pickReply(ctx: *task.Ctx, comm: []const u8) ![]const u8 { if (ctx.conf.smar_mode_enab) { if (ctx.draft) |drf| { const prm = try std.fmt.allocPrint(ctx.aren, "{s}{s}", .{ CF.aipr, comm }); if (drf(ctx, prm)) |txt| { const trm = std.mem.trim(u8, txt, " \r\n\""); if (trm.len > 0 and trm.len < 600) return trm; } else |_| {} } } const lst = ctx.conf.repl_temp_list; if (lst.len == 0) return CF.dflt; return lst[std.hash.Wyhash.hash(0, comm) % lst.len]; }
pub fn replRun(ctx: *task.Ctx, args: task.Args) !u32 { try task.visit(ctx, ctx.conf.path_noti_comm); const cms = try task.jsList(ctx, CF.read); var did: u32 = 0; for (cms, 0..) |comm, idx| { if (did >= args.maxn) break; const hsh = try task.hashHex(ctx, comm); const key = try std.fmt.allocPrint(ctx.aren, "repl|{s}", .{hsh}); const rep = try pickReply(ctx, comm); const what = try std.fmt.allocPrint(ctx.aren, "reply to \"{s}\" with \"{s}\"", .{ post.cutUtf8(comm, 40), post.cutUtf8(rep, 40) }); const stps = try ctx.aren.dupe(flow.Step, &.{ task.goStep(ctx.conf.path_noti_comm), .{ .op = .click, .labs = ctx.conf.labl_repl_btnz, .nth = idx }, .{ .op = .typez, .labs = ctx.conf.labl_comm_boxz, .text = rep }, .{ .op = .key, .text = "Enter", .commit = true } }); const out = task.execWrite(ctx, .comm, key, what, false, stps) catch |err| { if (err == error.NoElement or err == error.Drift or err == error.Dupe) { task.say(ctx, "skipped one comment ({s})", .{@errorName(err)}); continue; } return err; }; if (out != .dupe) did += 1; } return did; }
